function example_timeSeriesPreparation_internal_blockLength_1()  %#ok<DEFNU>
% EXAMPLE 1 of timeSeriesPreparation.internal.blockLength, verbatim from its help block.
    x = filter(1, [1 -0.9], randn(RandStream("twister", "Seed", 1), 2000, 1));
    b = timeSeriesPreparation.internal.blockLength(x);
end

function example_timeSeriesPreparation_internal_contentHash_1()  %#ok<DEFNU>
% EXAMPLE 1 of timeSeriesPreparation.internal.contentHash, verbatim from its help block.
    a = timeSeriesPreparation.internal.contentHash("qc", struct("hampelWindow", 61));
    b = timeSeriesPreparation.internal.contentHash("qc", struct("hampelWindow", 31));
end

function example_timeSeriesPreparation_internal_dlyap_1()  %#ok<DEFNU>
% EXAMPLE 1 of timeSeriesPreparation.internal.dlyap, verbatim from its help block.
    P = timeSeriesPreparation.internal.dlyap(0.9, 1, 1e-14, 60);
end

function example_timeSeriesPreparation_internal_fileSha256_1()  %#ok<DEFNU>
% EXAMPLE 1 of timeSeriesPreparation.internal.fileSha256, verbatim from its help block.
    f = tempname; fid = fopen(f, "w"); fwrite(fid, 'abc'); fclose(fid);
    h = timeSeriesPreparation.internal.fileSha256(f);
    delete(f);
end

function example_timeSeriesPreparation_internal_provenance_1()  %#ok<DEFNU>
% EXAMPLE 1 of timeSeriesPreparation.internal.provenance, verbatim from its help block.
    p = timeSeriesPreparation.internal.provenance("qc.hampel", Options=struct("Window", 61));
end

function example_timeSeriesPreparation_internal_requirePackage_1()  %#ok<DEFNU>
% EXAMPLE 1 of timeSeriesPreparation.internal.requirePackage, verbatim from its help block.
    timeSeriesPreparation.internal.requirePackage("timeSeriesPreparation", "example");
end

function example_timeSeriesPreparation_internal_resampleOnto_1()  %#ok<DEFNU>
% EXAMPLE 1 of timeSeriesPreparation.internal.resampleOnto, verbatim from its help block.
    t = int64(0:5:60)' * int64(1e9);
    y = sin((0:5:60)' / 20); y(7) = NaN;
    tq = int64(0:60)' * int64(1e9);
    yq = timeSeriesPreparation.internal.resampleOnto(t, y, isfinite(y), tq, "pchip", []);
end

function example_timeSeriesPreparation_internal_stageCache_1()  %#ok<DEFNU>
% EXAMPLE 1 of timeSeriesPreparation.internal.stageCache, verbatim from its help block.
    [outs, status] = timeSeriesPreparation.internal.stageCache("", "demo", "0", 1, @() magic(3));
end

